import{_ as o,a0 as e,w as r,s as u,ao as a,I as n,x as i,a1 as s,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Orbital Apps：新一代 Linux 程序 | LCTT x X-CMD","titleTemplate":false,"description":"Orbital Apps：新一代 Linux 程序 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Orbital Apps：新一代 Linux 程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Orbital Apps：新一代 Linux 程序 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180508 Orbital Apps - A New Generation Of Linux applications","title":"Orbital Apps：新一代 Linux 程序","tag":"201806","desc":""},"relativePath":"201806/20180508 Orbital Apps - A New Generation Of Linux applications.md","filePath":"[post].md"}'),d={name:"201806/20180508 Orbital Apps - A New Generation Of Linux applications.md"};function b(g,t,w,f,x,m){const l=e("Link");return r(),u("div",null,[t[21]||(t[21]=a('<h1 id="orbital-apps-新一代-linux-程序" tabindex="-1">Orbital Apps：新一代 Linux 程序 <a class="header-anchor" href="#orbital-apps-新一代-linux-程序" aria-label="Permalink to “Orbital Apps：新一代 Linux 程序”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/05/orbital-apps-720x340.jpg" alt=""></p><p>今天，我们要了解 <strong>Orbital Apps</strong> 或 <strong>ORB</strong>（<strong>O</strong>pen <strong>R</strong>unnable <strong>B</strong>undle）<strong>apps</strong>（开放可运行程序包），一个自由的、跨平台的开源程序集合。所有 ORB 程序都是可移动的。你可以将它们安装在你的 Linux 系统或 USB 驱动器上，以便你可以在任何系统上使用相同的程序。它们不需要 root 权限，并且没有依赖关系。所有必需的依赖关系都包含在程序中。只需将 ORB 程序复制到 USB 驱动器并将其插入到任何 Linux 系统中就立即开始使用它们。所有设置和配置以及程序的数据都将存储在 USB 驱动器上。由于不需要在本地驱动器上安装程序，我们可以在联机或脱机的计算机上运行应用程序。这意味着我们不需要 Internet 来下载任何依赖。</p><p>ORB 程序压缩了 60％，因此我们甚至可以从小型 USB 驱动器存储和使用它们。所有 ORB 应用程序都使用 PGP / RSA 进行签名，并通过 TLS 1.2 进行分发。所有应用程序打包时都不做任何修改，甚至不会重新编译。以下是当前可用的便携式 ORB 应用程序列表。</p><ul><li>abiword</li><li>audacious</li><li>audacity</li><li>darktable</li><li>deluge</li><li>filezilla</li><li>firefox</li><li>gimp</li><li>gnome-mplayer</li><li>hexchat</li><li>inkscape</li><li>isomaster</li><li>kodi</li><li>libreoffice</li><li>qbittorrent</li><li>sound-juicer</li><li>thunderbird</li><li>tomahawk</li><li>uget</li><li>vlc</li><li>未来还有更多</li></ul><p>Orb 是开源的，所以如果你是开发人员，欢迎协作并添加更多程序。</p><h3 id="下载并使用可移动-orb-程序" tabindex="-1">下载并使用可移动 ORB 程序 <a class="header-anchor" href="#下载并使用可移动-orb-程序" aria-label="Permalink to “下载并使用可移动 ORB 程序”">​</a></h3><p>正如我已经提到的，我们不需要安装可移动 ORB 程序。但是，ORB 团队强烈建议你使用 <strong>ORB 启动器</strong> 来获得更好的体验。 ORB 启动器是一个小的安装程序（小于 5MB），它可帮助你启动 ORB 程序，并获得更好，更流畅的体验。</p>',8)),n("p",null,[t[1]||(t[1]=i("让我们先安装 ORB 启动器。为此，",-1)),s(l,{href:"https://www.orbital-apps.com/documentation/orb-launcher-all-installers"},{default:p(()=>[...t[0]||(t[0]=[i("下载 ORB 启动器",-1)])]),_:1}),t[2]||(t[2]=i("。你可以手动下载 ORB 启动器的 ISO 并将其挂载到文件管理器上。或者在终端中运行以下任一命令来安装它：",-1))]),t[22]||(t[22]=a('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget -O - https://www.orbital-apps.com/orb.sh | bash</span></span></code></pre></div><p>如果你没有 wget，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl https://www.orbital-apps.com/orb.sh | bash</span></span></code></pre></div><p>询问时输入 root 用户和密码。</p><p>就是这样。Orbit 启动器已安装并可以使用。</p>',5)),n("p",null,[t[4]||(t[4]=i("现在，进入 ",-1)),s(l,{href:"https://www.orbital-apps.com/download/portable_apps_linux/"},{default:p(()=>[...t[3]||(t[3]=[i("ORB 可移动程序下载页面",-1)])]),_:1}),t[5]||(t[5]=i("，并下载你选择的程序。在本教程中，我会下载 Firefox。",-1))]),t[23]||(t[23]=a('<p>下载完后，进入下载位置并双击 ORB 程序来启动它。点击 Yes 确认。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/05/orbital-apps-1-2.png" alt=""></p><p>Firefox ORB 程序能用了！</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/05/orbital-apps-2.png" alt=""></p><p>同样，你可以立即下载并运行任何程序。</p><p>如果你不想使用 ORB 启动器，请将下载的 <code>.orb</code> 安装程序设置为可执行文件，然后双击它进行安装。不过，建议使用 ORB 启动器，它可让你在使用 ORB 程序时更轻松、更顺畅。</p><p>就我测试的 ORB 程序而言，它们打开即可使用。希望这篇文章有帮助。今天就是这些。祝你有美好的一天！</p><p>干杯！！</p><hr>',9)),n("p",null,[t[7]||(t[7]=i("via: ",-1)),s(l,{href:"https://www.ostechnix.com/orbitalapps-new-generation-ubuntu-linux-applications/"},{default:p(()=>[...t[6]||(t[6]=[i("https://www.ostechnix.com/orbitalapps-new-generation-ubuntu-linux-applications/",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=i("作者：",-1)),s(l,{href:"https://www.ostechnix.com/author/sk/"},{default:p(()=>[...t[8]||(t[8]=[i("SK",-1)])]),_:1}),t[13]||(t[13]=i(" 选题：",-1)),s(l,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[9]||(t[9]=[i("lujun9972",-1)])]),_:1}),t[14]||(t[14]=i(" 译者：",-1)),s(l,{href:"https://github.com/geekpi"},{default:p(()=>[...t[10]||(t[10]=[i("geekpi",-1)])]),_:1}),t[15]||(t[15]=i(" 校对：",-1)),s(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[11]||(t[11]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[18]||(t[18]=i("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[16]||(t[16]=[i("LCTT",-1)])]),_:1}),t[19]||(t[19]=i(" 原创编译，",-1)),s(l,{href:"https://linux.cn/"},{default:p(()=>[...t[17]||(t[17]=[i("Linux中国",-1)])]),_:1}),t[20]||(t[20]=i(" 荣誉推出",-1))])])}const B=o(d,[["render",b]]);export{T as __pageData,B as default};
